<script lang="ts">import { untrack } from "svelte"; import { useRuntime } from "../../../app/runtime.svelte"; import SystemFrame from "../../../components/SystemFrame.svelte"; import RouterLink from "../../../components/RouterLink.svelte"; import { createStorageProviderFormController } from "./storage-provider-form-controller.svelte"; const runtime = useRuntime(); const controller = untrack(() => createStorageProviderFormController({ onAuthenticationLost: runtime.requireLogin, onSystemAccessChange: runtime.access.setSystemAccess })); $effect(() => { void controller.keychains() }); async function create() { const p = await controller.create(); if (p) runtime.navigate(`/app/system/storage-providers/${encodeURIComponent(p.id)}`, true) }</script><SystemFrame active="storage-providers" title="New storage provider"><section class="system-page"><div class="system-page-heading mb-5"><div><p class="eyebrow">System</p><h2 class="title is-3">New storage provider</h2><p class="subtitle is-6">Credentials are write-only and cannot be viewed after saving.</p></div></div><form onsubmit={(e) => { e.preventDefault(); void create() }}><div class="field"><label class="label">Alias</label><div class="control"><input class="input" required bind:value={controller.state.form.alias} /></div></div><div class="field"><label class="label">Protocol</label><div class="control"><div class="select is-fullwidth"><select bind:value={controller.state.form.protocol}><option value="embedded">Embedded</option><option value="s3">S3</option></select></div></div></div><div class="field"><label class="label">Endpoint</label><div class="control"><input class="input" bind:value={controller.state.form.endpoint} /></div></div>{#if controller.state.form.protocol === "s3"}<div class="field"><label class="label">Region</label><div class="control"><input class="input" bind:value={controller.state.form.region} /></div></div><div class="field"><label class="label">Bucket</label><div class="control"><input class="input" bind:value={controller.state.form.bucket} /></div></div><div class="field"><label class="label">Access key ID</label><div class="control"><input class="input" bind:value={controller.state.form.accessKeyID} /></div></div><div class="field"><label class="label">Keychain</label><div class="control"><div class="select is-fullwidth"><select required bind:value={controller.state.form.keychain}><option value="">Select keychain</option>{#each controller.state.keychains as k (`${k.id}/${k.version}`)}<option value={k.id}>{k.id} / version {k.version}</option>{/each}</select></div></div></div><div class="field"><label class="label">Secret access key</label><div class="control"><input class="input" type="password" required bind:value={controller.state.form.secret} /></div></div>{/if}<div class="field is-grouped"><p class="control"><button class="button is-primary" disabled={controller.state.saving}>Add provider</button></p><p class="control"><RouterLink class="button" href="/app/system/storage-providers">Cancel</RouterLink></p></div></form>{#if controller.state.error}<p class="help is-danger">{controller.state.error}</p>{/if}</section></SystemFrame>
